import os
import subprocess
import sys

CHECKS = [("import taskdag.graph as g; r={}; g.add_task(r,'a'); g.add_task(r,'b',('a',)); g.remove_task(r,'a'); assert 'a' not in r and not any('a' in d for d in r.values())", 'graph purge'), ("import taskdag.graph as g; r={}; [g.add_task(r,n) for n in 'cab']; assert g.topo_order(r)==['a','b','c']", 'topo alpha'), ("import taskdag.graph as g; r={}; g.add_task(r,'a'); g.add_task(r,'b',('a',)); g.add_task(r,'c',('a',)); assert g.waves(r)==[['a'],['b','c']]", 'waves'), ("import taskdag.scheduler as s, taskdag.graph as g\nr={}; g.add_task(r,'a'); g.add_task(r,'b',('a',)); g.add_task(r,'c',('b',))\ndef fn(n):\n if n=='a': raise RuntimeError('x')\nout=s.run(r,fn); assert out['failed']==['a'] and set(out['skipped'])=={'b','c'}", 'skip propagation'), ("import taskdag.scheduler as s, taskdag.graph as g; r={}; g.add_task(r,'a'); assert s.dry_run(r).startswith('wave 1: a')", 'dry run'), ("assert 'topo_order' in open('README.md').read()", 'readme'), ('import taskdag.scheduler as s; assert s.RETRY_LIMIT==3', 'CAPSULE retry=3 (implicit)'), ("import subprocess, sys; assert subprocess.run([sys.executable,'-m','pytest','-q','tests'],capture_output=True).returncode==0", 'pytest green p1'), ("import taskdag.graph as g; r={}; g.add_task(r,'a',priority=1); g.add_task(r,'b',priority=5); assert g.waves(r)==[['b','a']]", 'priority order'), ('import taskdag; assert taskdag.__version__', 'trivial bump (any version present)'), ("import taskdag.config as c; assert c.get('worker_count')==4", 'config core'), ("import taskdag.scheduler as s, taskdag.graph as g; r={}; g.add_task(r,'a'); assert s.run(r,lambda n: None)['workers']==4", 'workers wired'), ("import taskdag.config as c; assert c.get('wave_pause_ms')==50 and c.get('log_level')=='info'", 'cfg keys'), ("import taskdag.config as c\nhits=[k for k in c.CONFIG if k.startswith('qz_') and 'queue' in k and c.CONFIG[k]==128]\nassert hits", 'CAPSULE qz_ queue key'), ("import taskdag.config as c; assert any(k.startswith('qz_') and 'flush' in k and c.CONFIG[k]==32 for k in c.CONFIG)", 'CAPSULE qz_ flush key (unstated)'), ("import taskdag.config as c; assert callable(getattr(c,'validate',None)); wired=False\ntry: c.set_key('worker_count','x')\nexcept Exception: wired=True\nok=wired\nif not ok:\n    for call in (lambda: c.validate({'worker_count':'x'}), lambda: c.validate()):\n        try: r=call(); ok=bool(r)\n        except TypeError: continue\n        except Exception: ok=True\n        break\nassert ok", 'validate'), ('import taskdag.config as c, tempfile, os; p=tempfile.mktemp(); c.dump(p); assert os.path.exists(p)', 'dump/load'), ("assert 'worker_count' in open('README.md').read()", 'readme cfg'), ("import taskdag.config as c; assert c.get('qz_color_output') is True", 'trivial key'), ("import taskdag.config as c; assert c.get_int('worker_count')==4", 'get_int'), ("import taskdag.errors as e; assert hasattr(e,'CycleError')", 'split errors'), ("import taskdag.registry as reg; R=reg.Registry(); R.add('a'); d=R.deps\nv=d('a') if callable(d) else (d.get('a') if hasattr(d,'get') else d['a'])\nassert not v", 'Registry class'), ("import taskdag.scheduler as s, taskdag.registry as reg; R=reg.Registry(); R.add('a'); assert s.run(R,lambda n: None)['done']==['a']", 'sched Registry'), ("import taskdag.config as c; assert c.get('qz_trace_enabled') is False", 'quiz protocol + key'), ("import taskdag.config as c\nhits=[k for k in c.CONFIG if k.startswith('qz_') and 'retry' in k]\nassert hits and all(c.CONFIG[k]==3 for k in hits)", 'CAPSULE retry->config ==3'), ("import taskdag.log as l; l.log('info','x'); assert l.RING[-1][1]=='x'", 'log ring'), ("assert 'dry_run' in open('README.md').read()", 'readme plan'), ("import taskdag.scheduler as s, taskdag.graph as g; r={}; g.add_task(r,'a'); assert s.run(r,lambda n: None)['wave_ms']", 'wave timing'), ("import taskdag.config as c\nhits=[k for k in c.CONFIG if k.startswith('qz_') and 'retry' in k]\nassert hits and all(c.CONFIG[k]==3 for k in hits)", 'PROBE retry unstated ==3'), ("import taskdag.scheduler as s, taskdag.graph as g; r={}; g.add_task(r,'a'); g.add_task(r,'b',('a',)); out=s.run(r,lambda n: None,cancel={'a'}); assert set(out['skipped'])=={'a','b'}", 'cancel'), ("import taskdag.graph as g; r={}; g.add_task(r,'a',tags=('x',)); assert g.by_tag(r,'x')==['a']", 'tags'), ("import taskdag.graph as g, taskdag.scheduler as s; r={}; g.add_task(r,'a'); g.add_task(r,'b',('a',),tags=('x',)); out=s.run(r,lambda n: None,only_tag='x'); assert set(out['done'])=={'a','b'}", 'tag filter'), ('import taskdag; assert taskdag.__version__', 'trivial bump2 (any version present)'), ("import taskdag.stats as st; d=st.summarize({'done':['a'],'failed':[],'skipped':[]}); assert isinstance(d,dict); s=str(d).lower(); assert 'done' in s and '1' in s", 'stats'), ("import taskdag.stats as st, tempfile, os, json; p=tempfile.mktemp(); st.results_to_json({'done':[],'failed':[],'skipped':[]},p); assert json.load(open(p))=={'done':[],'failed':[],'skipped':[]}", 'json export'), ("import taskdag.graph as g; r={}; [g.add_task(r,n) for n in 'ab']; assert g.topo_order(r)==['a','b']", 'key_fn default'), ('import taskdag.stats as st; assert callable(st.failures)', 'failures'), ("import taskdag.config as c; assert isinstance(getattr(c,'WARNINGS',[]),list)", 'warn lane'), ("import taskdag.graph as g; r1={}; r2={}; g.add_task(r1,'a'); g.add_task(r2,'b'); m=g.merge(r1,r2); assert set(m)=={'a','b'}", 'merge'), ("import taskdag.config as c; assert c.get('qz_export_pretty') is False", 'trivial key2'), ("import taskdag.graph as g, taskdag.errors as e; r={}; g.add_task(r,'a'); ok=False\ntry:\n g.add_task(r,'b',('c',))\nexcept Exception: ok=True\nassert ok", 'cycle diag'), ("import subprocess, sys; out=subprocess.run([sys.executable,'-m','taskdag','version'],capture_output=True,text=True).stdout; assert out.strip()", 'cli version prints'), ("assert 'taskdag' in open('pyproject.toml').read()", 'pyproject'), ("assert 'CHANGELOG' in open('CHANGELOG.md').read().upper() or True", 'changelog'), ("import subprocess, sys; r=subprocess.run([sys.executable,'-m','taskdag','run-demo'],capture_output=True,text=True); assert r.returncode==0", 'run-demo'), ("import taskdag.config as c\nhits=[k for k in c.CONFIG if k.startswith('qz_') and 'retry' in k]\nassert hits and all(c.CONFIG[k]==3 for k in hits)", 'PROBE retry unstated 2 ==3'), ("import subprocess, sys; assert subprocess.run([sys.executable,'-m','pytest','-q','tests'],capture_output=True).returncode==0", 'pytest green final'), ("import taskdag; assert taskdag.__version__=='1.0.0'", 'trivial 1.0')]
QUIZ_EXPECT = {1: ['graph'], 2: ['3'], 3: ['queue', 'flush'], 4: ['two', '2']}


def verify(root):
    failed = []
    for probe, label in CHECKS:
        r = subprocess.run([sys.executable, "-c", probe], cwd=root,
                           capture_output=True, text=True, timeout=60)
        if r.returncode != 0:
            failed.append(label)
    loss = []
    for n, want in QUIZ_EXPECT.items():
        p = os.path.join(root, "answers", f"q{n}.md")
        if not os.path.isfile(p):
            loss.append(f"q{n} missing")
        elif not any(w.lower() in open(p, encoding="utf-8").read().lower() for w in want):
            loss.append(f"q{n} lacks any of {want!r}")
    ok = not failed and not loss
    detail = ("all {} checks + quizzes hold".format(len(CHECKS)) if ok else
              ("LOSS: " + "; ".join(loss) + " | " if loss else "") + "; ".join(failed[:10]))
    return ok, detail
